class Order {
  std::unordered_map<std::string, std::any> props_;
public:
  void set(std::string name, std::any value) { props_[std::move(name)] = std::move(value); }
  bool has(const std::string& name) const { return props_.find(name) != props_.end(); }
  template <class T> std::optional<T> get(const std::string& name) const {
    auto it = props_.find(name);               // one hash lookup per access
    if (it == props_.end()) return std::nullopt;
    if (auto* p = std::any_cast<T>(&it->second)) return *p;
    return std::nullopt;                       // absent or wrong type
  }
};

